import java.io.*;import java.util.*;import java.util.zip.*;import java.security.*;import java.security.spec.*;import java.security.cert.*;import com.android.apksig.*;
public class SigningCompatibilityCheck {
 public static void main(String[] args)throws Exception{Random random=new Random(321);for(int n=0;n<512;n++){byte[] b=new byte[n];random.nextBytes(b);String wanted=java.util.Base64.getEncoder().encodeToString(b),actual=com.bananalab.signcompat.Base64.getEncoder().encodeToString(b);if(!wanted.equals(actual)||!Arrays.equals(b,com.bananalab.signcompat.Base64.getDecoder().decode(actual)))throw new AssertionError("base64");}for(String bad:new String[]{"A","=","A=","AA=","A===","====","AA\nAA","!AAA"}){try{com.bananalab.signcompat.Base64.getDecoder().decode(bad);throw new AssertionError("accepted invalid base64");}catch(IllegalArgumentException expected){}}List<Integer> list=new ArrayList<>(Arrays.asList(3,1,2));com.bananalab.signcompat.Compat.sort(list,Comparator.naturalOrder());if(!list.equals(Arrays.asList(1,2,3))||com.bananalab.signcompat.Compat.stream(list).mapToInt(x->x).sum()!=6)throw new AssertionError("stream/sort");try{com.bananalab.signcompat.Compat.toIntExact(1L<<40);throw new AssertionError("overflow");}catch(ArithmeticException expected){}byte[] pk,cert;try(ZipFile z=new ZipFile(args[0])){pk=z.getInputStream(z.getEntry("private-key.pk8")).readAllBytes();cert=z.getInputStream(z.getEntry("certificate.der")).readAllBytes();}PrivateKey key=KeyFactory.getInstance("RSA").generatePrivate(new PKCS8EncodedKeySpec(pk));X509Certificate certificate=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(cert));ApkSigner.SignerConfig config=new ApkSigner.SignerConfig.Builder("test-owner",key,Arrays.asList(certificate)).build();new ApkSigner.Builder(Arrays.asList(config)).setInputApk(new File(args[1])).setOutputApk(new File(args[2])).setMinSdkVersion(23).setV1SigningEnabled(true).setV2SigningEnabled(true).setV3SigningEnabled(true).build().sign();ApkVerifier.Result result=new ApkVerifier.Builder(new File(args[2])).setMinCheckedPlatformVersion(23).build().verify();if(!result.isVerified())throw new AssertionError(result.getErrors().toString());System.out.println("PASS signing compatibility:512 base64 round trips, rejection cases, sort/stream/overflow and actual v1/v2/v3 APK signature using adapted upstream engine");}
}
